export function setupPage(error: string): string {
  const safeError = escapeHtml(error);
  return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>راه‌اندازی Scraper 4</title><style>:root{color-scheme:dark}body{margin:0;background:#07111e;color:#e8eef8;font:15px Tahoma;line-height:2}main{max-width:780px;margin:40px auto;padding:25px}.card{background:#101e31;border:1px solid #29415f;border-radius:15px;padding:22px;margin-top:15px}h1{color:#38bdf8}.error{color:#fda4af;border-color:#be123c}b{color:#fcd34d}</style></head><body><main><h1>Scraper 4 روی Cloudflare Workers اجرا شد</h1><div class="card error"><b>راه‌اندازی کامل نشده است</b><br>${safeError}</div><div class="card"><h2>راه‌اندازی فقط از Dashboard</h2><ol><li>Worker را در Cloudflare Dashboard باز کنید.</li><li>به <b>Settings ← Variables and Secrets</b> بروید.</li><li>برای رمزگذاری اطلاعات اتصال، فقط <b>VAULT_SECRET</b> را با یک مقدار تصادفی حداقل ۸ کاراکتری به‌صورت Secret اضافه و Deploy کنید.</li></ol><p>ساخت D1، Queue و migration توسط Workers Builds خودکار است و terminal لازم نیست.</p></div></main></body></html>`;
}

