async function saveAutoRule(){const match=$('arRuleMatch').value,triggers=$('arRuleTriggers').value.trim(),reply=$('arRuleReply').value.trim();if(match!=='always'&&!triggers)throw Error('حداقل یک عبارت برای تطبیق بنویسید.');if(!reply)throw Error('متن پاسخ قاعده خالی است.');const rule={id:autoRuleEdit>=0?autoRules()[autoRuleEdit].id:crypto.randomUUID(),on:true,match,triggers,reply,priority:Number($('arRulePriority').value)||50,daily_max:100};if(autoRuleEdit>=0)autoRules()[autoRuleEdit]=rule;else autoRules().push(rule);$('arRuleForm').hidden=true;await saveSettings();renderAutoRules()}
async function restoreSettingsFile(file){
 const status=$('transferStatus');if(status)status.textContent='📄 فایل انتخاب شد: '+file.name;
 if(!confirm('همهٔ تنظیمات موجود با اطلاعات فایل «'+file.name+'» بازیابی شوند؟')){if(status)status.textContent='بازیابی لغو شد؛ هیچ تغییری انجام نشد.';return}
 if(status)status.textContent='⏳ در حال بررسی و بازیابی '+file.name+'…';
 try{
  const text=await file.text();if(!text.trim())throw Error('فایل انتخاب‌شده خالی است.');const raw=JSON.parse(text);if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ساختار فایل تنظیمات معتبر نیست.');
  const d=await api('/api/settings-import',{method:'POST',body:JSON.stringify(raw)});if(!d?.ok)throw Error(d?.error||'پاسخ بازیابی نامعتبر است.');await connect();
  const imported=d.imported||{};if(status)status.textContent='✅ بازیابی کامل شد: '+fa(imported.profiles||0)+' پروفایل، '+fa(imported.products||0)+' محصول، '+fa(imported.states||0)+' بخش تنظیمات و '+fa(imported.categories||0)+' یادگیری دسته‌بندی.';
  openResultModal('♻️ گزارش جامع بازیابی تنظیمات',{...d,summary:'فایل «'+file.name+'» با موفقیت بازیابی و رابط کاربری دوباره بارگذاری شد.',recommendations:(d.warnings||[]).length?['هشدارهای داخل گزارش را بازبینی کنید.']:['اکنون بخش‌های تنظیمات، اتصال‌ها و پروفایل‌ها اطلاعات بازیابی‌شده را نمایش می‌دهند.']});notice('تنظیمات و رابط‌های بصری دوباره بارگذاری شدند.');
 }catch(error){if(status)status.textContent='❌ بازیابی ناموفق: '+(error?.message||String(error));throw error}
}

